export function createAudioConfig(stream: MediaStream): AudioConfig {
  const audioTrack = stream.getAudioTracks()[0];
  const settings = audioTrack.getSettings();
  const capabilities = audioTrack.getCapabilities();

  return {
    sample_rate: settings.sampleRate || 48000,
    channels: settings.channelCount || 1,
    bits_per_sample: capabilities.sampleSize?.max || 16,
    encoding: 'linear16',
  };
}
